import * as React from "react";

import { cn } from "../lib/utils";

import styles from "./route-progress.module.css";

export type RouteProgressProps = {
  /** Whether a navigation is resolving; the app reads it from its router. */
  pending: boolean;
  className?: string;
};

/** A thin bar along the top of the viewport while the router resolves a navigation. */
export function RouteProgress({ pending, className }: RouteProgressProps) {
  const [run, setRun] = React.useState(0);
  React.useEffect(() => {
    if (pending) setRun((current) => current + 1);
  }, [pending]);
  let state = "idle";
  if (pending) state = "loading";
  else if (run > 0) state = "done";
  return (
    <div
      aria-hidden="true"
      data-slot="route-progress"
      data-state={state}
      className={cn(styles.progress, className)}
    >
      <div key={run} className={styles.bar} />
    </div>
  );
}
RouteProgress.displayName = "RouteProgress";

.progress {
  position: fixed;
  inset: 0 0 auto;
  z-index: 50;
  height: var(--v4-space-2);
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--v4-duration-moderate) var(--v4-ease-fade);
}
.progress[data-state="loading"] {
  opacity: 1;
  transition-delay: var(--v4-duration-slow);
}
.bar {
  height: 100%;
  background: var(--v4-ink);
  transform: scaleX(0);
  transform-origin: left;
}
.progress[data-state="loading"] > .bar {
  animation: trickle calc(var(--v4-duration-slow) * 40) var(--v4-ease-exit) forwards;
}
.progress[data-state="done"] > .bar {
  transform: scaleX(1);
}
@keyframes trickle {
  to {
    transform: scaleX(0.9);
  }
}
@media (prefers-reduced-motion: reduce) {
  .progress,
  .progress[data-state="loading"] {
    transition-duration: 0s;
  }
  .progress[data-state="loading"] > .bar {
    animation: none;
    transform: scaleX(1);
  }
}
